-- NiceSim5_Epic -- Nice Flight! simulator macro, generated by tools/make_macros.py
-- from a REAL flight: BULL-NOSE-2026-09-15-10-50-42.csv (flight starting at 1013 s).
-- 475 ft, 16:04, five climbs. Duration, Yo-yo, Rebound and both Records (its low of 87 ft is not under 60, so no Save). Long: 16 minutes.
--
-- Run: FrSky Suite toolbar > Run Macro > pick THIS folder, then click Resume
-- (the debugger pauses on line 1). If it asks to restart the simulator to
-- load the files, click CANCEL. Have the Nice Flight! page showing.
--
-- SPEED: how much faster than real life the flight is replayed. The widget
-- must run its flight clock at the SAME rate or the flight will be measured
-- short: Nice Flight! CFG > Data > Simulator time scale = SPEED (1, 4, 8 or
-- 16). At 8x this 16:07 flight takes about 132 seconds. Set both to 1
-- to watch the Live screen in real time.
local SPEED = 8

-- Controls, as MEASURED in the simulator with sim/NiceSimDiag (2026-09-17,
-- X14, Ethos 26.1.2), reading the real sources back after each call:
--   simulator.setAnalog(1, v)  = throttle. At rest (0) the template reads the
--                                brake as pulled = Landing mode; +100 = brake off.
--   simulator.setAnalog(2, v)  = elevator (any movement leaves Zoom)
--   simulator.setSwitch(7, v)  = the launch button: +100 -> Launch mode,
--                                -100 -> Zoom until the elevator moves.
local AN_THROTTLE, AN_ELEVATOR, SW_LAUNCH = 1, 2, 7

-- Telemetry. Any module/band/rx/physId reaches the model's Altitude sensor,
-- but the simulator flags every sensor LOST within ~0.25 s unless the radio
-- link looks alive, so RSSI and VFR frames go out with every altitude frame
-- and frames never stop for longer than FRAME_GAP real seconds (at 0.1 s the
-- sensor still flapped between alive and lost; measured 2026-09-17).
local PHYS_ID = 0x1A
local ALT_APP_ID, RX_APP_ID, RSSI_APP_ID, VFR_APP_ID = 0x0100, 0xF104, 0xF101, 0xF010
local RX_CV = 490
local FRAME_GAP = 0.03           -- tightened automatically if the sensor still drops out

local BRAKED = true        -- false = hand catch: the widget ends it after 20 s on the ground
local ALT = { 7, 49, 79, 85, 92, 98, 97, 97, 97, 98, 102, 104, 103, 105, 106, 107, 105, 104, 103, 104, 106, 110, 114, 121, 120, 118, 121, 126, 134, 140, 144, 145, 147, 154, 158, 163, 170, 168, 173, 179, 185, 190, 189, 193, 201, 202, 209, 218, 219, 221, 230, 235, 243, 251, 251, 259, 263, 269, 277, 275, 281, 287, 289, 299, 301, 302, 311, 313, 314, 320, 319, 325, 327, 330, 338, 340, 340, 344, 346, 351, 352, 354, 359, 360, 362, 366, 369, 369, 369, 372, 376, 376, 378, 380, 379, 383, 390, 387, 387, 388, 388, 397, 399, 395, 396, 396, 400, 400, 400, 404, 404, 410, 414, 411, 416, 419, 420, 419, 424, 428, 427, 421, 419, 421, 427, 427, 428, 433, 431, 431, 432, 432, 437, 439, 434, 439, 446, 443, 436, 429, 393, 366, 360, 376, 395, 405, 401, 396, 395, 394, 395, 394, 392, 393, 393, 391, 393, 392, 395, 397, 394, 385, 336, 344, 361, 333, 312, 278, 279, 296, 299, 290, 288, 290, 291, 289, 289, 286, 286, 287, 285, 284, 283, 283, 281, 277, 273, 273, 270, 271, 274, 271, 267, 265, 264, 268, 270, 268, 268, 263, 262, 265, 267, 265, 265, 264, 269, 273, 269, 262, 258, 254, 254, 246, 247, 250, 249, 251, 252, 251, 248, 243, 239, 237, 230, 226, 222, 221, 223, 225, 222, 218, 215, 216, 215, 210, 206, 205, 205, 204, 201, 201, 199, 197, 194, 191, 192, 193, 192, 190, 186, 185, 184, 183, 183, 179, 173, 174, 175, 174, 173, 171, 170, 166, 163, 160, 159, 160, 160, 154, 156, 157, 148, 145, 144, 145, 143, 141, 140, 136, 135, 140, 137, 131, 135, 137, 138, 137, 134, 134, 133, 133, 138, 142, 143, 142, 141, 136, 137, 138, 132, 128, 121, 118, 109, 102, 95, 95, 99, 100, 96, 99, 101, 101, 101, 102, 99, 91, 90, 88, 86, 88, 91, 92, 88, 91, 91, 95, 95, 96, 99, 100, 100, 99, 98, 100, 103, 107, 109, 113, 114, 116, 117, 119, 120, 120, 128, 136, 140, 140, 143, 148, 154, 155, 153, 158, 164, 167, 170, 173, 179, 182, 180, 188, 197, 198, 201, 200, 201, 208, 211, 214, 216, 217, 224, 226, 232, 231, 234, 242, 246, 251, 250, 256, 265, 266, 269, 274, 277, 283, 285, 287, 291, 292, 295, 297, 296, 301, 301, 302, 305, 308, 313, 315,